```
#include <DHT.h>

// Define the pin connections for the DHT22 sensor
#define DHTPIN 2
#define DHTTYPE DHT22

// Create a DHT object
DHT* dht = new DHT(dhtpin, dhttype);

// Function to calibrate the sensor
void calibrate() {
  int numReadings = 100; // number of readings to take
  int sumTemp = 0;
  int sumHum = 0;

  // Take multiple readings and calculate the average
  for (int i = 0; i < numReadings; i++) {
    int humidity = dht.readHumidity();
    int temperature = dht.readTemperature();
    sumTemp += temperature;
    sumHum += humidity;
    delay(100); // wait for 100ms between readings
  }

  // Calculate the average temperature and humidity
  float avgTemp = (float)sumTemp / numReadings;
  float avgHum = (float)sumHum / numReadings;

  // Print the average values
  Serial.print("Average Temperature: ");
  Serial.print(avgTemp);
  Serial.println(" C");
  Serial.print("Average Humidity: ");
  Serial.print(avgHum);
  Serial.println("%");

  // Store the calibrated values in eeprom
  EEPROM.put(0, avgTemp);
  EEPROM.put(1, avgHum);
}

void setup() {
  Serial.begin(9600);
}

void loop() {
  calibrate();
  delay(10000); // wait for 10 seconds between calibrations
}
```
