import { createContext, useState } from 'react';

const FeedbackContext = createContext();

const FeedbackProvider = ({ children }) => {
  const [feedbackForm, setFeedbackForm] = useState({
    questions: [
      { id: 1, text: 'How was the lecture?' },
      { id: 2, text: 'Was the material covered relevant to your needs?' },
      { id: 3, text: 'Were there any topics that were unclear?' },
    ],
    answers: {},
  });

  const handleAnswer = (questionId, answer) => {
    setFeedbackForm((prevForm) => {
      const newForm = { ...prevForm };
      newForm.answers[questionId] = answer;
      return newForm;
    });
  };

  return (
    <FeedbackContext.Provider value={{ feedbackForm, handleAnswer }}>
      {children}
    </FeedbackContext.Provider>
  );
};

export { FeedbackProvider };
```
