JavaScript:
```javascript
const svg = document.getElementById('pendulum-svg');
const penWidth = 2;
const penColor = 'black';
const gravity = 9.81; // m/s^2
const angle = document.getElementById('initial-angle').value;
const theta = angle * (Math.PI / 180);
const l = 100; // length of the pendulum (m)
const omega = 0; // initial angular velocity (rad/s)

function drawPendulum() {
  svg.clearRect(0, 0, svg.width, svg.height);
  svg.beginPath();
  svg.arc(svg.width / 2, svg.height / 2, l, 0, 2 * Math.PI);
  svg.strokeStyle = penColor;
  svg.lineWidth = penWidth;
  svg.stroke();
  svg.closePath();
}

function updatePendulum() {
  omega = omega + (-gravity / l) * Math.sin(theta);
  theta += omega;
  document.getElementById('pendulum-svg').appendChild(drawPendulum());
}

document.getElementById('release-button').addEventListener('click', () => {
  setInterval(updatePendulum, 16); // update every 16ms ( approx. 60fps)
});

drawPendulum();

export function stopPendulum() {
  omega = 0;
  theta = 0;
  clearInterval();
}
```
